def prompts() -> dict[str, list[dict]]:
    copy = []
    for full, k in COPY:
        words = full.split()
        first = " ".join(words[:k])
        copy.append({"user": f'Write exactly this sentence: "{full}"', "assistant": first})
        copy.append({"user": first, "assistant": ""})
    pend = []
    for passage, concept in PENDING:
        pend.append({"user": passage, "assistant": ""})  # B: bare passage, read cell at its last token
        pend.append({"user": passage + " It was a", "assistant": concept})  # A: read cell at the concept word
    return {"cap_copy": copy, "cap_pending": pend}


def capture() -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    for name, plist in prompts().items():
        out_path = OUT / f"{name}.pt"
        if out_path.exists():
            print(f"{name}: exists, skip")
            continue
        spec = {"layers": LAYERS, "prompts": plist, "positions": "last", "per_prompt": True}
        (OUT / f"{name}.spec.json").write_text(json.dumps(spec))
        print(f"{name}: {len(plist)} prompts x {len(LAYERS)} layers", flush=True)
        subprocess.run([sys.executable, str(ROOT / "tools" / "metric.py"), "capture",
