import json
dm = json.load(open('third_party/workspace-bench/evals/directed_modulation/items.json'))
import collections
c = collections.Counter(it['subfamily'] for it in dm['items'])
print('DM subfamilies:', c)
for sf in set(c) - {'pair'}:
    its = [it for it in dm['items'] if it['subfamily'] == sf]
    print(f"--- {sf} ({len(its)}):")
    for it in its[:2]:
        print('   prompt:', it['prompt'][:160].replace('\n',' | '))
        if it.get('assistant'): print('   asst:', it['assistant'][:80])
try:
    m = json.load(open('third_party/workspace-bench/evals/multi_concept_directed_modulation/items.json'))
    its = m['items']
    print(f"--- multi_concept DM ({len(its)}): render={its[0].get('eval_render')}")
    for it in its[:2]:
        print('   prompt:', it['prompt'][:200].replace('\n',' | '))
        if it.get('assistant'): print('   asst:', it['assistant'][:80])
        print('   keys:', [k for k in it.keys() if k not in ('prompt','assistant')][:10])
except Exception as e:
    print('multi_concept:', e)
EOF
